buy_code:
매수 = False
if {b1_start} <= 시분초 < {b1_end}:
    if 시가총액 < {b1_cap_max}:
        if (등락율 >= {b1_rate_min} and 등락율 <= {b1_rate_max} and 당일거래대금 >= {b1_day_money_min} and 초당거래대금 >= {b1_sec_money_min} and 초당거래대금 / 초당거래대금평균({b1_burst_win}, 1) >= {b1_burst_mult} and 체결강도 >= {b1_strength_min} and 전일동시간비 >= {b1_prev_ratio_min}):
            매수 = True
elif 시분초 < {b2_end}:
