            매수 = True
elif 시분초 < {b3_end}:
    if {b3_cap_lo} <= 시가총액 < {b3_cap_hi}:
        if (등락율 >= {b3_rate_min} and 등락율 <= {b3_rate_max} and 당일거래대금 >= {b3_day_money_min} and 초당거래대금 >= {b3_sec_money_min} and 초당거래대금 / 초당거래대금평균({b3_burst_win}, 1) >= {b3_burst_mult} and 체결강도 >= {b3_strength_min} and 전일동시간비 >= {b3_prev_ratio_min} and 현재가 >= 이동평균({b3_ma_win}, 1) * {b3_ma_mult}):
